#!/bin/bash

# Определение функции для запуска заданий
run_task() {
    echo "Running task $1"
    sleep 1  # Имитация выполнения задания
}

# Определение функции для запуска всех заданий
run_all_tasks() {
    local task_count=0
    while true; do
        ((task_count++))
        run_task "$task_count" &
    done
}

# Определение функции для ожидания завершения всех заданий
wait_for_tasks() {
    wait
}

# Точка входа
main() {
    run_all_tasks &
    wait_for_tasks
}

# Вызов точки входа
main

