#!/bin/bash

# Определение функции для запуска задачи
run_task() {
    echo "Running task $1"
    sleep 1  # Simulate task execution
    echo "Task $1 completed"
}

# Определение функции для обработки очереди задач
process_queue() {
    local queue=("$@")
    for task in "${queue[@]}"; do
        run_task "$task"
    done
}

# Определение функции для запуска задачи в фоне и ожидания её завершения
run_and_wait() {
    local task="$1"
    run_task "$task" &
    wait $!
}

# Определение функции для обработки очереди задач с ожиданием завершения каждого ребёнка
process_queue_with_wait() {
    local queue=("$@")
    for task in "${queue[@]}"; do
        run_and_wait "$task"
    done
}

# Определение функции для запуска задачи в фоне без ожидания
run_in_background() {
    local task="$1"
    run_task "$task" &
}

# Определение функции для обработки очереди задач без ожидания завершения
process_queue_without_wait() {
    local queue=("$@")
    for task in "${queue[@]}"; do
        run_in_background "$task"
    done
}

# Определение функции для запуска задачи в фоне и ожидания завершения всех ребёнков
run_all_and_wait() {
    local queue=("$@")
    for task in "${queue[@]}"; do
        run_task "$task" &
    done
    wait
}

# Определение функции для обработки очереди задач с ожиданием завершения всех ребёнков
process_queue_all_and_wait() {
    local queue=("$@")
