#!/bin/bash

# Видимый список из 12 задач
tasks=("task1" "task2" "task3" "task4" "task5" "task6" "task7" "task8" "task9" "task10" "task11" "task12")

# Функция для запуска задачи
run_task() {
    echo "Running $1"
    sleep 1  # Имитация выполнения задачи
}

# Функция для запуска пакета задач
run_package() {
    local package=("$@")
    for task in "${package[@]}"; do
        run_task "$task"
    done
}

# Основная функция для запуска всех задач с ожиданием между пакетами
dispatch_packages() {
    local package_size=3
    local num_tasks=${#tasks[@]}
    local num_packages=$(( (num_tasks + package_size - 1) / package_size ))

    for ((i = 0; i < num_packages; i++)); do
        start_index=$((i * package_size))
        end_index=$((start_index + package_size))
        package=("${tasks[@]:start_index:end_index}")
        run_package "${package[@]}"
        sleep 2  # Ожидание между пакетами
    done
}

# Точка входа
dispatch_packages

