    local slot=$1
    echo "Slot $slot freed"
}

# Функция для запуска ребёнка
start_child() {
    local slot=$1
    echo "Starting child with slot $slot"
    # Имитация работы ребёнка
    sleep 2
    echo "Child with slot $slot finished"
    free_slot $slot
}

# Функция для запуска процесса с ожиданием
dispatch() {
    local slot=$1
    echo "Dispatching with slot $slot"
    start_child $slot &
    wait $!
}

# Основная функция
main() {
    local slot=${slot_pool[0]}
    dispatch $slot
}

# Запуск основной функции
main

