create_pool() {
    local pool_size=$1
    local tasks=("$@")
    local pids=()

    for ((i=0; i<pool_size; i++)); do
        # Запуск задачи в фоновом режиме
        ${tasks[i]} &
        pids+=($!)
    done

    # Ожидание завершения всех задач в пуле
