#!/bin/bash

# Определение функции-обёртки
wrapper() {
    local args=("$@")
    local count=${args[-1]}
    unset args[-1]

    if (( count > 0 )); then
        # Запуск ядра с уменьшенным счётчиком
        core "${args[@]}" $((count - 1))
    fi
}

# Определение ядра с пулом из двух worker
core() {
    local args=("$@")
    local count=${args[-1]}
    unset args[-1]

    # Запуск двух worker в фоне
    worker "${args[@]}" $count &
    worker "${args[@]}" $count &

    # Ожидание завершения обоих worker
    wait
}

# Определение worker
worker() {
    local args=("$@")
    local count=${args[-1]}
    unset args[-1]

    if (( count > 0 )); then
        # Рекурсивный вызов wrapper с уменьшенным счётчиком
        wrapper "${args[@]}" $((count - 1))
    fi
}

# Точка входа
main() {
    local args=("$@")
    local count=${args[-1]}
    unset args[-1]

    # Запуск обёртки с исходным счётчиком
    wrapper "${args[@]}" $count
}

# Запуск программы с аргументами
main "$@"

