: ${GENERATIONS:=-1}
: ${BUDGET:=0}
: ${START:=0}
: ${CURRENT:=0}
: ${PEAK:=0}

echo "Starting with generations: $GENERATIONS, budget: $BUDGET, start: $START"

function create_child() {
    local new_budget=$((BUDGET - 1))
    local new_current=$((CURRENT + 1))
    echo "Creating child with budget: $new_budget, current: $new_current"
    if (( new_budget > 0 )); then
        create_child
    fi
}

function check_budget() {
    if (( BUDGET <= 0 )); then
        echo "Budget exhausted, stopping"
        return
    fi
    create_child
}

while (( GENERATIONS < 0 )); do
    ((GENERATIONS++))
    echo "Generation $GENERATIONS"
    check_budget
    if (( CURRENT > PEAK )); then
        PEAK=$CURRENT
    fi
    CURRENT=0
done

echo "Total generations: $GENERATIONS, peak processes: $PEAK"
'

