#!/bin/bash

# Определение ядра
kernel() {
    echo "Kernel executed"
}

# Определение обёртки с глубиной три
wrapper() {
    local depth=$1
    if [ "$depth" -eq 0 ]; then
        kernel
    else
        wrapper $((depth - 1))
    fi
}

# Точка входа
wrapper 3

