#!/bin/bash

# Определение функции для запуска одного конечного worker без потомков
function start_worker() {
    # Запуск worker в фоне
    nohup bash -c 'while true; do echo "Worker running"; sleep 1; done' > /dev/null 2>&1 &
}

# Основная функция для запуска
function main() {
    # Запуск одного worker
    start_worker

    # Ожидание завершения worker
    wait
}

# Точка входа
main

#!/bin/bash

# Contrast: Launch only one final worker without children after detachment

# Function to create a single worker process
create_worker() {
    # Launch a worker process in the background
    worker_pid=$(setsid -c bash -c 'while true; do echo "Worker running"; sleep 1; done' &)
    echo "Worker PID: $worker_pid"
}

# Main execution
main() {
    echo "Starting main process"
    create_worker
    echo "Main process detached"
}

# Execute the main function
main

