#!/bin/bash

# Определение функции для запуска producer
producer() {
    # Запуск бесконечного цикла
    while true; do
        # Создание нового процесса-потомка
        producer &
        # Ждем 1 секунду перед следующей итерацией
        sleep 1
    done
}

# Определение функции для запуска wrapper
wrapper() {
    # Запуск producer внутри wrapper
    producer
}

# Определение функции для запуска внешнего wrapper
outer_wrapper() {
    # Запуск wrapper внутри внешнего wrapper
    wrapper
}

# Точка входа: запуск внешнего wrapper
outer_wrapper

